-- Small synthetic demo schema for Global Social Media Analytics (MySQL 8).
-- This is not the original dataset or the presentation's reported totals.
CREATE DATABASE IF NOT EXISTS social_media_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE social_media_demo;
CREATE TABLE IF NOT EXISTS Users (user_id INT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, country VARCHAR(80) NOT NULL, joined_at DATE NOT NULL);
CREATE TABLE IF NOT EXISTS Posts (post_id INT PRIMARY KEY, user_id INT NOT NULL, content VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_posts_user FOREIGN KEY (user_id) REFERENCES Users(user_id));
CREATE TABLE IF NOT EXISTS Comments (comment_id INT PRIMARY KEY, post_id INT NOT NULL, user_id INT NOT NULL, comment_text VARCHAR(500) NOT NULL, commented_at DATETIME NOT NULL, CONSTRAINT fk_comments_post FOREIGN KEY (post_id) REFERENCES Posts(post_id), CONSTRAINT fk_comments_user FOREIGN KEY (user_id) REFERENCES Users(user_id));
CREATE TABLE IF NOT EXISTS Likes (like_id INT PRIMARY KEY, post_id INT NOT NULL, user_id INT NOT NULL, liked_at DATETIME NOT NULL, UNIQUE KEY uq_like_per_user_post (post_id,user_id), CONSTRAINT fk_likes_post FOREIGN KEY (post_id) REFERENCES Posts(post_id), CONSTRAINT fk_likes_user FOREIGN KEY (user_id) REFERENCES Users(user_id));
CREATE TABLE IF NOT EXISTS Followers (follower_id INT NOT NULL, followed_user_id INT NOT NULL, followed_at DATE NOT NULL, PRIMARY KEY (follower_id,followed_user_id), CONSTRAINT fk_followers_follower FOREIGN KEY (follower_id) REFERENCES Users(user_id), CONSTRAINT fk_followers_followed FOREIGN KEY (followed_user_id) REFERENCES Users(user_id), CONSTRAINT chk_not_self_follow CHECK (follower_id <> followed_user_id));
CREATE TABLE IF NOT EXISTS Hashtags (hashtag_id INT PRIMARY KEY, hashtag_text VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Post_hashtags (post_id INT NOT NULL, hashtag_id INT NOT NULL, PRIMARY KEY (post_id,hashtag_id), CONSTRAINT fk_ph_post FOREIGN KEY (post_id) REFERENCES Posts(post_id), CONSTRAINT fk_ph_tag FOREIGN KEY (hashtag_id) REFERENCES Hashtags(hashtag_id));
